// context-model-bindgen deterministically records the Context Model schema
// bundle and emits the small language bindings used at the product boundary.
// It intentionally uses only the Go standard library.
package main

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"flag"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

const generatorVersion = "context-model-bindgen/v1"

type inputFile struct {
	Name   string `json:"name"`
	SHA256 string `json:"sha256"`
}

type manifest struct {
	GeneratorVersion string      `json:"generatorVersion"`
	Inputs           []inputFile `json:"inputs"`
	BundleSHA256     string      `json:"bundleSha256"`
}

func main() {
	root := flag.String("root", "contracts/context-model/v1", "Context Model schema directory")
	goOutput := flag.String("go-output", "internal/contextmodel/generated_v1.go", "generated Go output")
	manifestOutput := flag.String("manifest-output", "contracts/context-model/v1/generated-manifest.json", "generated manifest output")
	typescriptOutput := flag.String("typescript-output", "", "optional generated TypeScript output")
	check := flag.Bool("check", false, "fail when outputs differ")
	flag.Parse()
	schema, err := bundle(*root)
	if err != nil {
		fail(err)
	}
	manifestBytes, err := json.MarshalIndent(schema, "", "  ")
	if err != nil {
		fail(err)
	}
	manifestBytes = append(manifestBytes, '\n')
	if err := writeOrCheck(*manifestOutput, manifestBytes, *check); err != nil {
		fail(err)
	}
	goBindingBytes, err := format.Source([]byte(goBinding(schema.BundleSHA256)))
	if err != nil {
		fail(err)
	}
	if err := writeOrCheck(*goOutput, goBindingBytes, *check); err != nil {
		fail(err)
	}
	if *typescriptOutput != "" {
		if err := writeOrCheck(*typescriptOutput, []byte(typeScriptBinding(schema.BundleSHA256)), *check); err != nil {
			fail(err)
		}
	}
}

func bundle(root string) (manifest, error) {
	entries, err := os.ReadDir(root)
	if err != nil {
		return manifest{}, err
	}
	result := manifest{GeneratorVersion: generatorVersion}
	parts := []string{generatorVersion}
	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".schema.json") {
			continue
		}
		contents, err := os.ReadFile(filepath.Join(root, entry.Name()))
		if err != nil {
			return manifest{}, err
		}
		digest := sha256.Sum256(contents)
		result.Inputs = append(result.Inputs, inputFile{Name: entry.Name(), SHA256: hex.EncodeToString(digest[:])})
	}
	sort.Slice(result.Inputs, func(i, j int) bool { return result.Inputs[i].Name < result.Inputs[j].Name })
	for _, input := range result.Inputs {
		parts = append(parts, input.Name+":"+input.SHA256)
	}
	digest := sha256.Sum256([]byte(strings.Join(parts, "\n")))
	result.BundleSHA256 = hex.EncodeToString(digest[:])
	return result, nil
}

func writeOrCheck(path string, contents []byte, check bool) error {
	if check {
		actual, err := os.ReadFile(path)
		if err != nil || string(actual) != string(contents) {
			return fmt.Errorf("generated Context Model output is stale: %s", path)
		}
		return nil
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	return os.WriteFile(path, contents, 0o644)
}

func goBinding(digest string) string {
	return "// Code generated by " + generatorVersion + "; DO NOT EDIT.\npackage contextmodel\n\nconst GeneratedContextModelBundleSHA256 = \"" + digest + "\"\n\n// GeneratedCanonicalSourceRecord is the Go binding for source-record.schema.json.\ntype GeneratedCanonicalSourceRecord struct {\n\tSchemaVersion string `json:\"schemaVersion\"`\n\tID string `json:\"id\"`\n\tType string `json:\"type\"`\n\tName string `json:\"name\"`\n\tExtensions map[string]any `json:\"extensions,omitempty\"`\n\tCreatedAt string `json:\"createdAt\"`\n\tUpdatedAt string `json:\"updatedAt\"`\n\tRecordRevision int64 `json:\"recordRevision\"`\n\tCanonicalRevision int64 `json:\"canonicalRevision\"`\n}\n\n// GeneratedCanonicalContextItem is the Go binding for context-item.schema.json.\ntype GeneratedCanonicalContextItem struct {\n\tSchemaVersion string `json:\"schemaVersion\"`\n\tID string `json:\"id\"`\n\tSource GeneratedCanonicalItemSource `json:\"source\"`\n\tContent GeneratedCanonicalContent `json:\"content\"`\n\tProvenance GeneratedCanonicalProvenance `json:\"provenance\"`\n\tAttributes GeneratedCanonicalAttributes `json:\"attributes,omitempty\"`\n\tExtensions map[string]any `json:\"extensions,omitempty\"`\n\tRecordRevision int64 `json:\"recordRevision\"`\n\tCanonicalRevision int64 `json:\"canonicalRevision\"`\n}\ntype GeneratedCanonicalItemSource struct { ID string `json:\"id\"`; Type string `json:\"type\"`; ExternalID string `json:\"externalId\"`; Connector string `json:\"connector,omitempty\"` }\ntype GeneratedCanonicalContent struct { Format string `json:\"format\"`; Title string `json:\"title\"`; Body string `json:\"body\"`; Summary string `json:\"summary,omitempty\"` }\ntype GeneratedCanonicalProvenance struct { SourceURI string `json:\"sourceURI,omitempty\"`; Locator string `json:\"locator,omitempty\"`; CreatedAt string `json:\"createdAt,omitempty\"`; UpdatedAt string `json:\"updatedAt,omitempty\"`; ObservedAt string `json:\"observedAt\"`; ContentHash string `json:\"contentHash\"`; RecordHash string `json:\"recordHash\"` }\ntype GeneratedCanonicalAttributes struct { Tags []string `json:\"tags,omitempty\"`; Visibility string `json:\"visibility,omitempty\"`; Confidence string `json:\"confidence,omitempty\"`; Stale bool `json:\"stale,omitempty\"`; WebURL string `json:\"webURL,omitempty\"` }\n\n// GeneratedContextProfile is the v1 canonical profile schema binding.\ntype GeneratedContextProfile struct { SchemaVersion string `json:\"schemaVersion\"`; ID string `json:\"id\"`; Name string `json:\"name\"`; Description string `json:\"description,omitempty\"`; Sources []GeneratedProfileSource `json:\"sources\"`; IncludeTags []string `json:\"includeTags,omitempty\"`; ExcludeTags []string `json:\"excludeTags,omitempty\"`; IncludeGlobs []string `json:\"includeGlobs,omitempty\"`; ExcludeGlobs []string `json:\"excludeGlobs,omitempty\"`; Visibility []string `json:\"visibility,omitempty\"`; Privacy map[string]any `json:\"privacy,omitempty\"`; Freshness map[string]any `json:\"freshness,omitempty\"`; Retrieval map[string]any `json:\"retrieval,omitempty\"`; CreatedAt string `json:\"createdAt\"`; UpdatedAt string `json:\"updatedAt\"`; RecordRevision int64 `json:\"recordRevision\"`; CanonicalRevision int64 `json:\"canonicalRevision\"` }\ntype GeneratedProfileSource struct { SourceID string `json:\"sourceId\"`; Folders []string `json:\"folders,omitempty\"`; Tags []string `json:\"tags,omitempty\"`; Files []string `json:\"files,omitempty\"`; Collections []string `json:\"collections,omitempty\"`; Databases []string `json:\"databases,omitempty\"` }\n\n// GeneratedContextItemBatch is the v1 source-scoped producer mutation binding.\ntype GeneratedContextItemBatch struct { SchemaVersion string `json:\"schemaVersion\"`; Mode string `json:\"mode\"`; Items []GeneratedCanonicalContextItem `json:\"items\"`; Deletions []string `json:\"deletions\"` }\n\n// GeneratedContextPack is the v1 portable Agent Context export binding.\ntype GeneratedContextPack struct { SchemaVersion string `json:\"schemaVersion\"`; ID string `json:\"id\"`; Digest string `json:\"digest\"`; GeneratedAt string `json:\"generatedAt\"`; ContractDigest string `json:\"contractDigest\"`; Request GeneratedContextPackRequest `json:\"request\"`; Evidence []GeneratedContextPackEvidence `json:\"evidence\"` }\ntype GeneratedContextPackRequest struct { Query string `json:\"query\"`; ProfileID string `json:\"profileId\"`; Limit int `json:\"limit\"`; RetrievalState string `json:\"retrievalState\"`; CanonicalRevision int64 `json:\"canonicalRevision,omitempty\"`; ProfileRevision int64 `json:\"profileRevision,omitempty\"`; IndexInputRevision int64 `json:\"indexInputRevision,omitempty\"`; IndexGeneration int64 `json:\"indexGeneration,omitempty\"` }\ntype GeneratedContextPackEvidence struct { ItemID string `json:\"itemId\"`; ChunkID string `json:\"chunkId\"`; Content string `json:\"content\"`; HeadingPath []string `json:\"headingPath,omitempty\"`; Citation GeneratedContextPackCitation `json:\"citation\"`; Source GeneratedContextPackSource `json:\"source\"`; ContentHash string `json:\"contentHash\"`; ObservedAt string `json:\"observedAt\"` }\ntype GeneratedContextPackCitation struct { Title string `json:\"title\"`; Path string `json:\"path\"`; StartLine int `json:\"startLine\"`; EndLine int `json:\"endLine\"` }\ntype GeneratedContextPackSource struct { ID string `json:\"id\"`; Type string `json:\"type\"`; ExternalID string `json:\"externalId\"`; URI string `json:\"uri,omitempty\"` }\n"
}

func typeScriptBinding(digest string) string {
	return "// Code generated by " + generatorVersion + "; DO NOT EDIT.\nexport const contextModelBundleSha256 = \"" + digest + "\" as const;\nexport type GeneratedCanonicalSourceRecord = { schemaVersion: string; id: string; type: string; name: string; extensions?: Record<string, unknown>; createdAt: string; updatedAt: string; recordRevision: number; canonicalRevision: number };\nexport type GeneratedCanonicalContextItem = { schemaVersion: string; id: string; source: { id: string; type: string; externalId: string; connector?: string }; content: { format: \"text\" | \"markdown\" | \"html\"; title: string; body: string; summary?: string }; provenance: { sourceURI?: string; locator?: string; createdAt?: string; updatedAt?: string; observedAt: string; contentHash: string; recordHash: string }; attributes?: { tags?: string[]; visibility?: \"private\" | \"team\" | \"public\"; confidence?: \"low\" | \"medium\" | \"high\"; stale?: boolean; webURL?: string }; extensions?: Record<string, unknown>; recordRevision: number; canonicalRevision: number };\nexport type GeneratedContextProfile = { schemaVersion: string; id: string; name: string; description?: string; sources: Array<{ sourceId: string; folders?: string[]; tags?: string[]; files?: string[]; collections?: string[]; databases?: string[] }>; includeTags?: string[]; excludeTags?: string[]; includeGlobs?: string[]; excludeGlobs?: string[]; visibility?: Array<\"private\" | \"team\" | \"public\">; privacy?: Record<string, unknown>; freshness?: Record<string, unknown>; retrieval?: Record<string, unknown>; createdAt: string; updatedAt: string; recordRevision: number; canonicalRevision: number };\nexport type GeneratedContextItemBatch = { schemaVersion: string; mode: \"incremental\" | \"snapshot\"; items: GeneratedCanonicalContextItem[]; deletions: string[] };\nexport type GeneratedContextPack = { schemaVersion: string; id: string; digest: string; generatedAt: string; contractDigest: string; request: { query: string; profileId: string; limit: number; retrievalState: \"indexed\" | \"fallback\"; canonicalRevision?: number; profileRevision?: number; indexInputRevision?: number; indexGeneration?: number }; evidence: Array<{ itemId: string; chunkId: string; content: string; headingPath?: string[]; citation: { title: string; path: string; startLine: number; endLine: number }; source: { id: string; type: string; externalId: string; uri?: string }; contentHash: string; observedAt: string }> };\n"
}

func fail(err error) { fmt.Fprintln(os.Stderr, err); os.Exit(1) }
